"use strict"

// Export Node.js internal encodings.
// Encodings

// Codec.

// ------------------------------------------------------------------------------
// Use utf8 for decoding.

// Add decoder for versions of Node not supporting CESU-8

// ------------------------------------------------------------------------------

// We use node.js internal decoder. Its signature is the same as ours.

// ------------------------------------------------------------------------------
// Encoder is mostly trivial

// ------------------------------------------------------------------------------
// Except base64 encoder, which must keep its state.

// ------------------------------------------------------------------------------
// CESU-8 encoder is also special.
// Naive implementation, but it works because CESU-8 is especially easy
// to convert from UTF-16 (which all JS strings are encoded in).
// charCode will always be < 0x10000 in javascript.

// ------------------------------------------------------------------------------
// CESU-8 decoder is not implemented in Node v4.0+
// Leading byte
// Previous code is invalid
// Single-byte code
// Two-byte code
// Three-byte code
// Four or more are not supported for CESU-8.
// Continuation byte
// We're waiting for it.
// Check for overlong encoding, but support Modified UTF-8 (encoding NULL as C0 80)
// Actually add character.
// Unexpected continuation byte

// ------------------------------------------------------------------------------
// check the chunk boundaries for surrogate pair
var Buffer = require("safer-buffer").Buffer

module.exports = {
  utf8: { type: "_internal", bomAware: true },
  cesu8: { type: "_internal", bomAware: true },
  unicode11utf8: "utf8",

  ucs2: { type: "_internal", bomAware: true },
  utf16le: "ucs2",

  binary: { type: "_internal" },
  base64: { type: "_internal" },
  hex: { type: "_internal" },
  _internal: InternalCodec,
}

function InternalCodec(codecOptions, iconv) {
  this.enc = codecOptions.encodingName
  this.bomAware = codecOptions.bomAware

  if (
    this.enc ===
    "base64"
  ) {
    this.encoder = InternalEncoderBase64
  } else if (
    this.enc ===
    "utf8"
  ) {
    this.encoder = InternalEncoderUtf8
  } else if (
    this.enc ===
    "cesu8"
  ) {
    this.enc = "utf8"
    this.encoder = InternalEncoderCesu8
    if (
      Buffer.from("eda0bdedb2a9", "hex").toString() !==
      "💩"
    ) {
      this.decoder = InternalDecoderCesu8
      this.defaultCharUnicode = iconv.defaultCharUnicode
    }
  }
}

InternalCodec.prototype.encoder = InternalEncoder
InternalCodec.prototype.decoder = InternalDecoder
var StringDecoder = require("string_decoder").StringDecoder

function InternalDecoder(options, codec) {
  this.decoder = new StringDecoder(codec.enc)
}

InternalDecoder.prototype.write = function (buf) {
  if (!Buffer.isBuffer(buf)) {
    buf = Buffer.from(buf)
  }

  return this.decoder.write(buf)
}

InternalDecoder.prototype.end = function () {
  return this.decoder.end()
}

function InternalEncoder(options, codec) {
  this.enc = codec.enc
}

InternalEncoder.prototype.write = function (str) {
  return Buffer.from(str, this.enc)
}

InternalEncoder.prototype.end = function () {}

function InternalEncoderBase64(options, codec) {
  this.prevStr = ""
}

InternalEncoderBase64.prototype.write = function (str) {
  str =
    this.prevStr +
    str
  var completeQuads = str.length - (str.length % 4)
  this.prevStr = str.slice(completeQuads)
  str = str.slice(0, completeQuads)

  return Buffer.from(str, "base64")
}

InternalEncoderBase64.prototype.end = function () {
  return Buffer.from(this.prevStr, "base64")
}

function InternalEncoderCesu8(options, codec) {}

InternalEncoderCesu8.prototype.write = function (str) {
  var buf = Buffer.alloc(
    str.length *
      3,
  )
  var bufIdx = 0
  for (
    var i = 0;
    i <
    str.length;
    i++
  ) {
    var charCode = str.charCodeAt(i)
    if (
      charCode <
      0x80
    ) {
      buf[bufIdx++] = charCode
    } else if (
      charCode <
      0x800
    ) {
      buf[bufIdx++] = 0xc0 + (charCode >>> 6)
      buf[bufIdx++] = 0x80 + (charCode & 0x3f)
    } else {
      buf[bufIdx++] = 0xe0 + (charCode >>> 12)
      buf[bufIdx++] = 0x80 + ((charCode >>> 6) & 0x3f)
      buf[bufIdx++] = 0x80 + (charCode & 0x3f)
    }
  }
  return buf.slice(0, bufIdx)
}

InternalEncoderCesu8.prototype.end = function () {}

function InternalDecoderCesu8(options, codec) {
  this.acc = 0
  this.contBytes = 0
  this.accBytes = 0
  this.defaultCharUnicode = codec.defaultCharUnicode
}

InternalDecoderCesu8.prototype.write = function (buf) {
  var acc = this.acc
  var contBytes = this.contBytes
  var accBytes = this.accBytes
  var res = ""
  for (
    var i = 0;
    i <
    buf.length;
    i++
  ) {
    var curByte = buf[i]
    if ((curByte & 0xc0) !== 0x80) {
      if (
        contBytes >
        0
      ) {
        res += this.defaultCharUnicode
        contBytes = 0
      }

      if (
        curByte <
        0x80
      ) {
        res += String.fromCharCode(curByte)
      } else if (
        curByte <
        0xe0
      ) {
        acc =
          curByte &
          0x1f
        contBytes = 1
        accBytes = 1
      } else if (
        curByte <
        0xf0
      ) {
        acc =
          curByte &
          0x0f
        contBytes = 2
        accBytes = 1
      } else {
        res += this.defaultCharUnicode
      }
    } else {
      if (
        contBytes >
        0
      ) {
        acc = (acc << 6) | (curByte & 0x3f)
        contBytes--
        accBytes++
        if (
          contBytes ===
          0
        ) {
          if (
            accBytes ===
              2 &&
            acc <
              0x80 &&
            acc >
              0
          ) {
            res += this.defaultCharUnicode
          } else if (
            accBytes ===
              3 &&
            acc <
              0x800
          ) {
            res += this.defaultCharUnicode
          } else {
            res += String.fromCharCode(acc)
          }
        }
      } else {
        res += this.defaultCharUnicode
      }
    }
  }
  this.acc = acc
  this.contBytes = contBytes
  this.accBytes = accBytes
  return res
}

InternalDecoderCesu8.prototype.end = function () {
  var res = 0
  if (
    this.contBytes >
    0
  ) {
    res += this.defaultCharUnicode
  }
  return res
}

function InternalEncoderUtf8(options, codec) {
  this.highSurrogate = ""
}

InternalEncoderUtf8.prototype.write = function (str) {
  if (this.highSurrogate) {
    str = this.highSurrogate + str
    this.highSurrogate = ""
  }

  if (str.length > 0) {
    var charCode = str.charCodeAt(str.length - 1)
    if (charCode >= 0xd800 && charCode < 0xdc00) {
      this.highSurrogate = str[str.length - 1]
      str = str.slice(0, str.length - 1)
    }
  }

  return Buffer.from(str, this.enc)
}

InternalEncoderUtf8.prototype.end = function () {
  if (this.highSurrogate) {
    var str = this.highSurrogate
    this.highSurrogate = ""
    return Buffer.from(str, this.enc)
  }
}
